{"content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Office Building Simulation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; font-family: sans-serif; }
        canvas { display: block; }
        #ui {
            position: absolute;
            top: 10px;
            left: 10px;
            color: white;
            background: rgba(0, 0, 0, 0.7);
            padding: 10px;
            border-radius: 5px;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="ui">
        <h2 style="margin: 0 0 5px 0;">Office Simulation</h2>
        <p style="margin: 0;">Floors: <span id="floor-count">0</span></p>
        <p style="margin: 0;">Active Workers: <span id="worker-count">0</span></p>
    </div>
    <!-- Use a CDN for Three.js, hoping file:// allows it. 
         If not, I'll need to implement a very simple 3D/Pseudo-3D engine. -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
    <script>
        // --- Configuration ---
        const BUILDING_FLOORS = 5;
        const FLOOR_HEIGHT = 4;
        const BUILDING_WIDTH = 20;
        const BUILDING_DEPTH = 30;
        const WORKER_COUNT = 20;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87ceeb); // Sky blue

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(40, 40, 40);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lights ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const sunLight = new THREE.DirectionalLight(0xffffff, 1.0);
        sunLight.position.set(50, 100, 50);
        sunLight.castShadow = true;
        sunLight.shadow.mapSize.width = 2048;
        sunLight.shadow.mapSize.height = 2048;
        scene.add(sunLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(1000, 1000);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Building Structure
        const floors = [];
        const buildingGroup = new THREE.Group();
        scene.add(buildingGroup);

        for (let i = 0; i < BUILDING_FLOORS; i++) {
            const floorGroup = new THREE.Group();
            floorGroup.position.y = i * FLOOR_HEIGHT;

            // Floor slab
            const slabGeo = new THREE.BoxGeometry(BUILDING_WIDTH, 0.2, BUILDING_DEPTH);
            const slabMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa });
            const slab = new THREE.Mesh(slabGeo, slabMat);
            slab.receiveShadow = true;
            floorGroup.add(slab);

            // Walls (Simplified)
            const wallMat = new THREE.MeshStandardMaterial({ color: 0xffffff, side: THREE.DoubleSide });

            // Front wall
            const frontWall = new THREE.Mesh(new THREE.BoxGeometry(BUILDING_WIDTH, FLOOR_HEIGHT, 0.5), wallMat);
            frontWall.position.set(0, FLOOR_HEIGHT / 2, BUILDING_DEPTH / 2);
            frontWall.castShadow = true;
            frontWall.receiveShadow = true;
            floorGroup.add(frontWall);

            // Back wall
            const backWall = new THREE.Mesh(new THREE.BoxGeometry(BUILDING_WIDTH, FLOOR_HEIGHT, 0.5), wallMat);
            backWall.position.set(0, FLOOR_HEIGHT / 2, -BUILDING_DEPTH / 2);
            backWall.castShadow = true;
            backWall.receiveShadow = true;
            floorGroup.add(backWall);

            // Side walls
            const sideWallL = new THREE.Mesh(new THREE.BoxGeometry(0.5, FLOOR_HEIGHT, BUILDING_DEPTH), wallMat);
            sideWallL.position.set(-BUILDING_WIDTH / 2, FLOOR_HEIGHT / 2, 0);
            sideWallL.castShadow = true;
            sideWallL.receiveShadow = true;
            floorGroup.add(sideWallL);

            const sideWallR = new THREE.Mesh(new THREE.BoxGeometry(0.5, FLOOR_HEIGHT, BUILDING_DEPTH), wallMat);
            sideWallR.position.set(BUILDING_WIDTH / 2, FLOOR_HEIGHT / 2, 0);
            sideWallR.castShadow = true;
            sideWallR.receiveShadow = true;
            floorGroup.add(sideWallR);

            buildingGroup.add(floorGroup);
            floors.push(floorGroup);
        }

        // Elevator
        const elevatorGeo = new THREE.BoxGeometry(3, FLOOR_HEIGHT * 0.8, 3);
        const elevatorMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
        const elevator = new THREE.Mesh(elevatorGeo, elevatorMat);
        elevator.position.set(BUILDING_WIDTH / 2 - 2, 0, 0);
        elevator.castShadow = true;
        buildingGroup.add(elevator);

        // --- Workers ---
        const workers = [];
        const workerGeo = new THREE.BoxGeometry(0.5, 1.5, 0.5);

        function createWorker() {
            const mat = new THREE.MeshStandardMaterial({ color: Math.random() * 0xffffff });
            const worker = new THREE.Mesh(workerGeo, mat);
            worker.castShadow = true;

            // State
            worker.userData = {
                floor: Math.floor(Math.random() * BUILDING_FLOORS),
                targetX: (Math.random() - 0.5) * (BUILDING_WIDTH - 5),
                targetZ: (Math.random() - 0.5) * (BUILDING_DEPTH - 5),
                state: 'working', // working, movingToElevator, inElevator, movingToFloor
                speed: 0.05 + Math.random() * 0.05,
                elevatorTargetFloor: 0
            };

            // Initial position
            worker.position.set(
                worker.userData.targetX,
                worker.userData.floor * FLOOR_HEIGHT + 1,
                worker.userData.targetZ
            );

            scene.add(worker);
            workers.push(worker);
        }

        for (let i = 0; i < WORKER_COUNT; i++) {
            createWorker();
        }

        // --- Animation Loop ---
        let lastTime = performance.now();
        function animate() {
            requestAnimationFrame(animate);
            const now = performance.now();
            const delta = (now - lastTime) / 1000;
            lastTime = now;

            // Elevator Logic
            elevator.position.y = 0; // Reset
            // Simple elevator logic: cycle through floors
            const elevatorSpeed = 2.0;
            const elevatorTargetY = (Math.floor(Date.now() / 5000) % BUILDING_FLOORS) * FLOOR_HEIGHT + (FLOOR_HEIGHT / 2);
            elevator.position.y += (elevatorTargetY - elevator.position.y) * 0.02;

            // Worker Logic
            workers.forEach(worker => {
                const data = worker.userData;

                if (data.state === 'working') {
                    // Move slowly towards desk
                    worker.position.x += (data.targetX - worker.position.x) * 0.01;
                    worker.position.z += (data.targetZ - worker.position.z) * 0.01;

                    // Randomly decide to go to elevator
                    if (Math.random() < 0.001) {
                        data.state = 'movingToElevator';
                        data.targetX = BUILDING_WIDTH / 2 - 2;
                        data.targetZ = 0;
                    }
                } else if (data.state === 'movingToElevator') {
                    worker.position.x += (data.targetX - worker.position.x) * 0.02;
                    worker.position.z += (data.targetZ - worker.position.z) * 0.02;

                    if (Math.abs(worker.position.x - data.targetX) < 0.1 && Math.abs(worker.position.z - data.targetZ) < 0.1) {
                        data.state = 'inElevator';
                        data.elevatorTargetFloor = Math.floor(Math.random() * BUILDING_FLOORS);
                    }
                } else if (data.state === 'inElevator') {
                    // Teleport to elevator height
                    worker.position.x = elevator.position.x;
                    worker.position.z = elevator.position.z;

                    // Move worker with elevator
                    const targetY = data.elevatorTargetFloor * FLOOR_HEIGHT + 1;
                    worker.position.y += (targetY - worker.position.y) * 0.05;

                    // If elevator is at target floor
                    if (Math.abs(worker.position.y - targetY) < 0.5) {
                        data.state = 'movingToFloor';
                        data.targetX = (Math.random() - 0.5) * (BUILDING_WIDTH - 5);
                        data.targetZ = (Math.random() - 0.5) * (BUILDING_DEPTH - 5);
                    }
                } else if (data.state === 'movingToFloor') {
                    worker.position.x += (data.targetX - worker.position.x) * 0.02;
                    worker.position.z += (data.targetZ - worker.position.z) * 0.02;

                    if (Math.abs(worker.position.x - data.targetX) < 0.1 && Math.abs(worker.position.z - data.targetZ) < 0.1) {
                        data.state = 'working';
                    }
                }
            });

            renderer.render(scene, camera);
        }

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();

        // Update UI
        document.getElementById('floor-count').innerText = BUILDING_FLOORS;
        document.getElementById('worker-count').innerText = WORKER_COUNT;
    </script>
</body>
</html>
"}

